setRunOnMount(true)

const k = 50
const s = 44100;
const curve = new Float32Array(s);
const deg = Math.PI / 180;

for (let i = 0; i < s; i++) {
  const x = (i * 2) / s - 1;

  curve[i] = ((3 + k) * x * 20 * deg)
    / (Math.PI + k * Math.abs(x));
}

send(curve)

setVideoOutput(true)

setHidePorts(true)

function setup() {
  createCanvas(252, 164)
  pixelDensity(4)
  strokeWeight(1)
}

function draw() {
  clear()
  noStroke();

  const waveform = fft().a
  const spectrum = fft({type: 'freq'}).a
  if (!waveform || !spectrum) return

  const sl = spectrum.length / 5
  for (let i = 0; i< sl; i++){
    let x = map(i, 0, sl, 0, width);
    let h = map(spectrum[i], 0, 250, height, 0) - height;
    // fill(255, spectrum[i], 100);
    // rect(x, height, width / sl, h)
  }

  noFill();
  beginShape();
  stroke('white');
  for (let i = 0; i < waveform.length; i++){
    let x = map(i, 0, waveform.length, 0, width);
    let y = map( waveform[i], 0, 256, 0, height);
    vertex(x,y);
  }
  endShape();
}
